"""Supply current-material guidance and state-fidelity examples; delegate tools."""

from pydantic import JsonValue

from experimental.curator.harness.preparation import PreparationRequest
from experimental.curator.harness.resources import (
    CapabilityContribution,
    CapabilityRegistrar,
    CapabilitySelection,
    RegistrationReceipt,
    SelectionRequest,
    SkillContribution,
    SkillSelection,
)
from experimental.curator.harness.state import Task
from experimental.curator.harness.strategies import CapabilityStrategy


SKILL_NAME = "comparison-state-fidelity"
SKILL_SOURCE = "curator-capability"
SKILL_ASSET = "skills/comparison-state-fidelity/SKILL.md"

GUIDANCE = """以当前请求指定的本次工作规则、竞品资料和汇率表为准，不沿用旧任务口径。先定位并读适用规则，路径不明时用已有目录发现能力查找，再据其范围使用资料；截断时续读所需部分，同次完整且仍适用的内容直接复用。表格对象、方向、取值、价格换算、单位精度、定位称呼及位置都从当次规则确定，事实与汇率只取当次材料，需要计算时使用已有能力。
填写功能格及选择定位项时，先对照随本次输入提供的 comparison-state-fidelity 案例正文；正文已给出，不另行读取。先按产品名×功能名保留原值并作允许映射，再据同一组状态按当次定义逐家判断定位资格。交付前将每个功能格对回原资料，并核对定位与这些状态一致；修正差异，不为突出定位而改格或删掉其他功能。只陈列有依据的事实，不评价竞品好坏。
缺项依本次规则处理，不猜填；保留有依据的内容，不用计划、进度或省略解释代替规定交付。最终只输出本次要求的表格和一句定位正文，不附开场白、过程说明、案例或核对记录。"""


class CurrentMaterialCapability(CapabilityStrategy):
    """Prepare one example skill and select it without storing session progress."""

    def __init__(self, registrar: CapabilityRegistrar) -> None:
        self._registrar = registrar

    def _prepare_skills(self, request: PreparationRequest) -> tuple[SkillContribution, ...]:
        text = request.assets.get(SKILL_ASSET)
        if text is None or not text.strip():
            raise ValueError(f"Missing or empty required skill asset: {SKILL_ASSET}")
        return (
            SkillContribution(
                name=SKILL_NAME,
                owner="capability",
                package=None,
                files={"SKILL.md": text},
                source="task-feedback:R1-R2",
            ),
        )

    def register(self, contribution: CapabilityContribution) -> RegistrationReceipt:
        return self._registrar.register(contribution)

    async def select(self, request: SelectionRequest) -> CapabilitySelection:
        matches = [
            skill for skill in request.skills
            if skill.name == SKILL_NAME and skill.source == SKILL_SOURCE
        ]
        if len(matches) != 1:
            raise ValueError(f"Required skill is missing or ambiguous: {SKILL_SOURCE}/{SKILL_NAME}")
        target = matches[0]
        if not target.available:
            raise ValueError(f"Required skill is unavailable: {target.source}/{target.name}")
        # Body content is loaded by the host after selection, not in this request.
        selected = (SkillSelection(name=target.name, source=target.source, delivery="body"),)
        selected += tuple(
            SkillSelection(name=skill.name, source=skill.source, delivery="catalog")
            for skill in request.skills
            if skill.available and (skill.source, skill.name) != (target.source, target.name)
        )
        return CapabilitySelection(tools=None, skills=selected, guidance=GUIDANCE)


def create(
    state: dict[str, JsonValue],
    task: Task,
    *,
    registrar: CapabilityRegistrar,
) -> CurrentMaterialCapability:
    """Bind the registrar without mutating the task or session checkpoint."""
    return CurrentMaterialCapability(registrar)
